n = int(input())
counts = {}
for _ in range(n):
    languages = {input() for _ in range(int(input()))}
    for language in languages:
        counts[language] = counts.get(language, 0) + 1
common = sorted(language for language in counts if counts[language] == n)
print(len(common))
for language in common:
    print(language)
print(len(counts))
for language in sorted(counts):
    print(language)
